refentry.refsect1:
&reftitle.parameters;




   connection

    &pgsql.parameter.connection-with-unspecified-default;



   query



     Una riga di testo da inviare direttamente al backend PostgreSQL. Un terminatore
     NULL viene aggiunto automaticamente.

  &reftitle.examples;



    Esempio di pg_put_line


<?php 
  $conn = pg_pconnect("dbname=foo");
  pg_query($conn, "create table bar (a int4, b char(16), d float8)");
  pg_query($conn, "copy bar from stdin");
  pg_put_line($conn, "3\tciao mondo\t4.5\n");
  pg_put_line($conn, "4\taddio mondo\t7.11\n");
  pg_put_line($conn, "\\.\n");
  pg_end_copy($conn);
?>
